            if multi:
                while c-3>=1 and c-3 not in a and (c-3)%3!=2 and c-3 not in (2,5,8,11):
                    pass
            # simpler: single step -1 segment if free
            nc=c-3
            if nc>=1 and nc not in a:
                a[a.index(c)]=nc; moved=True
        if not moved: break
    return sorted(a)
